function (settings, time, ctx) {
  // ---------- SETTINGS ----------
  var ANGLE_UNIT     = settings.angle_unit.value;      // 'decideg' (INAV attitude[]) | 'deg' | 'rad'
  var INVERT_ROLL    = settings.invert_roll.value;     // flip the roll direction
  var INVERT_PITCH   = settings.invert_pitch.value;    // flip the pitch direction
  var PITCH_GAIN     = settings.pitch_gain.value;      // ball degrees per degree of pitch (real instruments exaggerate pitch; 1 = true scale)
  var SMOOTH_MS      = settings.smooth_ms.value;       // smoothing window in ms, centered on the current time (0 = off)
  var SKY            = settings.sky.value;             // sky color
  var GROUND         = settings.ground.value;          // ground color
  var HORIZON        = settings.horizon_line.value;    // horizon line color
  var LADDER         = settings.ladder_color.value;    // pitch lines and numbers color
  var LADDER_STEP    = settings.ladder_step.value;     // degrees between numbered pitch lines (a short line halfway between)
  var LADDER_SIZE    = settings.ladder_size.value;     // pitch number font size at the default 320x320 size; scales with the widget
  var BALL_SIZE      = settings.ball_size.value;       // ball diameter in % of the glass opening (>100: the ball edge hides behind the bezel)
  var SHADING        = settings.shading.value;         // darkening of the ball edge and bezel shadow 0..1 (sphere effect)
  var GLARE          = settings.glare.value;           // light reflection on the ball 0..1
  var BANK_MODE      = settings.bank_mode.value;       // 'pointer' = fixed scale, pointer turns with the ball | 'scale' = scale turns with the ball, fixed index
  var FULL_RING      = settings.full_ring.value;       // bank ticks all around the dial (off = only up to +-90)
  var BANK_NUMBERS   = settings.bank_numbers.value;    // numbers at the 30, 60, 90 ... bank ticks
  var BANK_SIZE      = settings.bank_size.value;       // bank number font size at the default size; scales with the widget
  var BEZEL_WIDTH    = settings.bezel_width.value;     // bezel ring width at the default 320x320 size; scales with the widget
  var BEZEL          = settings.bezel.value;           // bezel ring color
  var TICK_COLOR     = settings.tick_color.value;      // bank tick color
  var POINTER        = settings.pointer_color.value;   // moving bank pointer (triangle on the ball) color
  var INDEX_COLOR    = settings.index_color.value;     // fixed index triangle color
  var AIRCRAFT       = settings.aircraft_symbol.value; // draw the fixed miniature aircraft
  var AIRCRAFT_COLOR = settings.aircraft_color.value;  // aircraft symbol color
  var FONT           = settings.font.value;            // font family
  var OPACITY        = settings.opacity.value;         // whole-widget opacity 0..1 (1 = opaque)
  // -------------------------------
  var W = ctx.width, H = ctx.height, S = Math.min(W, H), scale = S / 320;
  var cx = W / 2, cy = H / 2;
  var Rb = S / 2 - 1.5 * scale;              // bezel outer radius
  var bw = BEZEL_WIDTH * scale;              // bezel ring width
  var Ro = Rb - bw;                          // glass opening radius (everything of the ball is clipped to it)
  var R = Ro * BALL_SIZE / 100;              // ball radius
  var PI = Math.PI, D2R = PI / 180;
  function f(n) { return (Math.round(n * 100) / 100).toString(); }
  function rgba(a) { return 'rgba(0,0,0,' + (Math.max(0, Math.min(1, a))).toFixed(3) + ')'; }
  function white(a) { return 'rgba(255,255,255,' + (Math.max(0, Math.min(1, a))).toFixed(3) + ')'; }
  function stop(o, c) { return '<stop offset="' + o + '%" stop-color="' + c + '"/>'; }

  // ---- data
  var roll = ctx.values[0], pitch = ctx.values[1];
  var k = ANGLE_UNIT === 'decideg' ? 0.1 : ANGLE_UNIT === 'rad' ? 180 / PI : 1;
  var hasData = typeof roll === 'number' || typeof pitch === 'number';
  // centered moving average over +-SMOOTH_MS/2 with triangular weights; only when the raw value exists
  // (outside the flight ctx.range still returns the edge samples). Roll wraps at +-180: circular mean.
  function smoothAngle(col, cur, circular) {
    if (typeof cur !== 'number') return cur;
    if (!(SMOOTH_MS > 0) || !col) return cur * k;          // no smoothing: just the unit conversion
    var sam = ctx.range(col, time - SMOOTH_MS / 2, time + SMOOTH_MS / 2, 200) || [], sx = 0, sy = 0, ws = 0, j, wgt, r;
    for (j = 0; j < sam.length; j++) {
      if (typeof sam[j].v !== 'number') continue;
      wgt = 1 - Math.abs(sam[j].t - time) / (SMOOTH_MS / 2); if (wgt <= 0) continue;
      if (circular) { r = sam[j].v * k * D2R; sx += Math.cos(r) * wgt; sy += Math.sin(r) * wgt; }
      else sx += sam[j].v * k * wgt;
      ws += wgt;
    }
    if (!ws) return cur * k;
    return circular ? Math.atan2(sy, sx) / D2R : sx / ws;
  }
  roll = smoothAngle(ctx.columns[0], roll, true);
  pitch = smoothAngle(ctx.columns[1], pitch, false);
  roll = typeof roll === 'number' ? roll : 0;
  pitch = typeof pitch === 'number' ? pitch : 0;
  if (INVERT_ROLL) roll = -roll;
  if (INVERT_PITCH) pitch = -pitch;
  var tb = Math.max(-89.9, Math.min(89.9, pitch * PITCH_GAIN)) * D2R;   // ball pitch (rotation about the lateral axis)
  var sinT = Math.sin(tb), cosT = Math.cos(tb);

  // ---- static part: defs, bezel, ticks, shading, aircraft (built once per size + look)
  var s = ctx.state;
  var lookKey = [W, H, SKY, GROUND, LADDER, BALL_SIZE, SHADING, GLARE, FULL_RING, BANK_NUMBERS, BANK_SIZE, BEZEL_WIDTH, BEZEL,
    TICK_COLOR, POINTER, INDEX_COLOR, AIRCRAFT, AIRCRAFT_COLOR, FONT].join('|');
  if (s.lookKey !== lookKey) {
    var bsz = BANK_SIZE * scale;
    s.defs = '<defs>'
      + '<clipPath id="__ID__o"><circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(Ro) + '"/></clipPath>'
      // limb darkening of the sphere (light from the top left: darker band wider at the bottom right)
      + '<radialGradient id="__ID__l" cx="50%" cy="50%" r="50%" fx="41%" fy="37%">'
      + stop(0, rgba(0)) + stop(42, rgba(0)) + stop(64, rgba(SHADING * 0.18)) + stop(80, rgba(SHADING * 0.5)) + stop(90, rgba(SHADING * 0.75)) + stop(100, rgba(SHADING * 0.98)) + '</radialGradient>'
      // broad sheen on the upper left of the ball
      + '<radialGradient id="__ID__g" cx="35%" cy="31%" r="46%">'
      + stop(0, white(GLARE * 0.62)) + stop(35, white(GLARE * 0.28)) + stop(100, white(0)) + '</radialGradient>'
      // crisp specular glare
      + '<radialGradient id="__ID__h" cx="50%" cy="50%" r="50%">'
      + stop(0, white(GLARE * 0.9)) + stop(55, white(GLARE * 0.4)) + stop(100, white(0)) + '</radialGradient>'
      // shadow of the bezel falling onto the ball (light from the top left: the shadow band is wider there)
      + '<radialGradient id="__ID__s" cx="50%" cy="50%" r="50%" fx="46%" fy="44%">'
      + stop(0, rgba(0)) + stop(74, rgba(0)) + stop(88, rgba(SHADING * 0.32)) + stop(100, rgba(SHADING * 0.9)) + '</radialGradient>'
      // metal bevel of the bezel
      + '<linearGradient id="__ID__m" x1="0" y1="0" x2="1" y2="1">' + stop(0, white(0.55)) + stop(50, white(0.18)) + stop(100, white(0.04)) + '</linearGradient>'
      + '<linearGradient id="__ID__n" x1="0" y1="0" x2="1" y2="1">' + stop(0, rgba(0.7)) + stop(50, rgba(0.25)) + stop(100, white(0.35)) + '</linearGradient>'
      + '</defs>';
    // shading layers (screen fixed, never rotate with the ball)
    var gx = cx - R * 0.40, gy = cy - R * 0.44;
    s.shade = '<circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(R) + '" fill="url(#__ID__g)"/>'
      + '<circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(R) + '" fill="url(#__ID__l)"/>'
      + '<ellipse cx="' + f(gx) + '" cy="' + f(gy) + '" rx="' + f(R * 0.21) + '" ry="' + f(R * 0.095) + '" transform="rotate(-42 ' + f(gx) + ' ' + f(gy) + ')" fill="url(#__ID__h)"/>'
      + '<circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(Ro) + '" fill="url(#__ID__s)"/>';
    // bezel ring with bevelled edges
    s.bezel = '<circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f((Rb + Ro) / 2) + '" fill="none" stroke="' + BEZEL + '" stroke-width="' + f(bw + 1) + '"/>'
      + '<circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(Rb - 1 * scale) + '" fill="none" stroke="url(#__ID__m)" stroke-width="' + f(2 * scale) + '"/>'
      + '<circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(Ro + 1 * scale) + '" fill="none" stroke="url(#__ID__n)" stroke-width="' + f(2 * scale) + '"/>';
    // bank ticks: two paths (short / long) + optional numbers, drawn around 0 = top
    var angles = FULL_RING ? [10, 20, 30, 45, 60, 90, 120, 150, 180] : [10, 20, 30, 45, 60, 90];
    var shortP = '', longP = '', nums = '', i, a, sign, big, r1, r2, p1, p2;
    for (i = 0; i < angles.length; i++) {
      for (sign = -1; sign <= 1; sign += 2) {
        if (angles[i] === 180 && sign === 1) continue;
        a = angles[i] * sign * D2R;
        big = angles[i] >= 60 || angles[i] === 30;
        r1 = Ro + 1.5 * scale; r2 = r1 + bw * (big ? 0.55 : 0.34);
        p1 = [cx + r1 * Math.sin(a), cy - r1 * Math.cos(a)];
        p2 = [cx + r2 * Math.sin(a), cy - r2 * Math.cos(a)];
        var seg = 'M' + f(p1[0]) + ',' + f(p1[1]) + 'L' + f(p2[0]) + ',' + f(p2[1]);
        if (big) longP += seg; else shortP += seg;
        if (BANK_NUMBERS && angles[i] % 30 === 0)
          nums += '<text transform="rotate(' + (angles[i] * sign) + ' ' + f(cx) + ' ' + f(cy) + ') translate(' + f(cx) + ',' + f(cy - Rb + bw * 0.16) + ')" text-anchor="middle" font-family="' + FONT
            + '" font-size="' + f(bsz) + '" fill="' + TICK_COLOR + '">' + angles[i] + '</text>';
      }
    }
    s.ticks = '<path d="' + shortP + '" stroke="' + TICK_COLOR + '" stroke-width="' + f(1.6 * scale) + '" fill="none"/>'
      + '<path d="' + longP + '" stroke="' + TICK_COLOR + '" stroke-width="' + f(2.6 * scale) + '" fill="none"/>' + nums;
    // fixed index at the top of the bezel (points into the opening)
    var ih = 12 * scale, iw = 7 * scale;
    s.index = '<path d="M' + f(cx) + ',' + f(cy - Ro - 1 * scale) + ' L' + f(cx - iw) + ',' + f(cy - Ro - 1 * scale - ih) + ' L' + f(cx + iw) + ',' + f(cy - Ro - 1 * scale - ih) + ' Z" fill="' + INDEX_COLOR
      + '" stroke="' + rgba(0.55) + '" stroke-width="' + f(1 * scale) + '" stroke-linejoin="round"/>';
    // moving pointer at the top of the ball (in ball coordinates, centre 0,0)
    s.pointer = '<path d="M0,' + f(-(Ro - 1.5 * scale)) + ' L' + f(-iw) + ',' + f(-(Ro - 1.5 * scale - ih)) + ' L' + f(iw) + ',' + f(-(Ro - 1.5 * scale - ih)) + ' Z" fill="' + POINTER
      + '" stroke="' + rgba(0.55) + '" stroke-width="' + f(1 * scale) + '" stroke-linejoin="round"/>';
    // miniature aircraft: wing bars with a V to the centre dot
    var wa = Ro * 0.56, wc = Ro * 0.24, wd = Ro * 0.11, wing = 'M' + f(cx - wa) + ',' + f(cy) + ' L' + f(cx - wc) + ',' + f(cy) + ' L' + f(cx - wc / 2) + ',' + f(cy + wd) + ' L' + f(cx) + ',' + f(cy)
      + ' L' + f(cx + wc / 2) + ',' + f(cy + wd) + ' L' + f(cx + wc) + ',' + f(cy) + ' L' + f(cx + wa) + ',' + f(cy);
    s.plane = AIRCRAFT ? '<path d="' + wing + '" fill="none" stroke="' + rgba(0.6) + '" stroke-width="' + f(7.5 * scale) + '" stroke-linejoin="round" stroke-linecap="round"/>'
      + '<path d="' + wing + '" fill="none" stroke="' + AIRCRAFT_COLOR + '" stroke-width="' + f(4.5 * scale) + '" stroke-linejoin="round" stroke-linecap="round"/>'
      + '<circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(3.2 * scale) + '" fill="' + AIRCRAFT_COLOR + '" stroke="' + rgba(0.6) + '" stroke-width="' + f(1.5 * scale) + '"/>' : '';
    s.lookKey = lookKey;
  }
  var uid = (s.uid || (s.uid = 'u' + Math.random().toString(36).slice(2, 8))) + (s.frame = ((s.frame || 0) + 1) % 1000000);
  function id(str) { return str.split('__ID__').join(uid); }

  // ---- ball (coordinates relative to the centre; the whole group rotates with roll)
  // sphere of radius R, pitch axis horizontal: the horizon and the pitch lines are latitude circles
  // seen from the front = ellipse arcs; the ball is larger than the opening so their curvature shows
  var sy = R * sinT, ry = Math.max(0.01, Math.abs(sy));
  var horizon = 'M' + f(-R) + ',0 A' + f(R) + ',' + f(ry) + ' 0 0 ' + (sy >= 0 ? 0 : 1) + ' ' + f(R) + ',0';
  var ball = '<circle r="' + f(R + 1) + '" fill="' + SKY + '"/>'
    + '<path d="' + horizon + ' A' + f(R + 1) + ',' + f(R + 1) + ' 0 0 1 ' + f(-R) + ',0 Z" fill="' + GROUND + '"/>'
    + '<path d="' + horizon + '" fill="none" stroke="' + HORIZON + '" stroke-width="' + f(1.6 * scale) + '"/>';
  // pitch ladder
  var step = Math.max(1, LADDER_STEP), lsz2 = LADDER_SIZE * scale, lines = '', texts = '', p, phi, sp, cp, s2, as, ta, te, yc, b, x1, y1, x2, y2, lam, half, arc;
  for (p = -90 + step / 2; p < 90; p += step / 2) {
    if (Math.abs(p) < 0.01) continue;
    phi = p * PITCH_GAIN * D2R;
    if (Math.abs(phi) >= 89 * D2R) continue;
    sp = Math.sin(phi); cp = Math.cos(phi);
    s2 = -(sp / cp) * (sinT / cosT);                    // visible where sin(t) > s2 (front hemisphere)
    if (s2 >= 1) continue;
    as = s2 <= -1 ? -PI / 2 : Math.asin(s2);
    half = Math.abs(Math.round(p / (step / 2)) % 2) === 1; // short line halfway between numbered ones
    lam = (half ? 11 : 21) * D2R;                      // half length in longitude
    ta = Math.max(as, PI / 2 - lam); te = Math.min(PI - as, PI / 2 + lam);
    if (te - ta < 0.02) continue;
    yc = -R * sp * cosT; b = R * cp * sinT;
    x1 = R * cp * Math.cos(ta); y1 = yc + b * Math.sin(ta);
    x2 = R * cp * Math.cos(te); y2 = yc + b * Math.sin(te);
    if (Math.abs(y1) > Ro + lsz2 && Math.abs(y2) > Ro + lsz2) continue; // outside the opening anyway
    arc = Math.abs(b) < 0.05 ? ' L' : ' A' + f(R * cp) + ',' + f(Math.abs(b)) + ' 0 0 ' + (b > 0 ? 1 : 0) + ' ';
    lines += 'M' + f(x1) + ',' + f(y1) + arc + f(x2) + ',' + f(y2);
    if (!half)
      texts += '<text x="' + f(x1 + 5 * scale) + '" y="' + f(y1) + '" dy="0.35em" font-family="' + FONT + '" font-size="' + f(lsz2) + '" fill="' + LADDER + '">' + Math.abs(Math.round(p)) + '</text>'
        + '<text x="' + f(x2 - 5 * scale) + '" y="' + f(y2) + '" dy="0.35em" text-anchor="end" font-family="' + FONT + '" font-size="' + f(lsz2) + '" fill="' + LADDER + '">' + Math.abs(Math.round(p)) + '</text>';
  }
  ball += '<path d="' + lines + '" fill="none" stroke="' + LADDER + '" stroke-width="' + f(1.5 * scale) + '" stroke-linecap="round"/>' + texts;

  var rot = ' rotate(' + f(-roll) + ')';
  var flag = hasData ? '' : '<g transform="translate(' + f(cx) + ',' + f(cy + Ro * 0.55) + ')"><rect x="' + f(-30 * scale) + '" y="' + f(-9 * scale) + '" width="' + f(60 * scale) + '" height="' + f(18 * scale) + '" rx="' + f(2 * scale)
    + '" fill="#c62828" stroke="#fff" stroke-width="' + f(1 * scale) + '"/><text y="' + f(3.5 * scale) + '" text-anchor="middle" font-family="' + FONT + '" font-size="' + f(10 * scale) + '" font-weight="bold" fill="#fff">NO DATA</text></g>';

  return '<svg width="' + f(W) + '" height="' + f(H) + '" style="display:block;opacity:' + OPACITY + '">'
    + id(s.defs)
    + '<g clip-path="url(#' + uid + 'o)">'
    + '<g transform="translate(' + f(cx) + ',' + f(cy) + ')' + rot + '">' + ball + '</g>'
    + id(s.shade)
    + '<g transform="translate(' + f(cx) + ',' + f(cy) + ')' + rot + '">' + s.pointer + '</g>'   // pointer above the shading: stays bright
    + '</g>'
    + s.plane
    + id(s.bezel)
    + (BANK_MODE === 'scale' ? '<g transform="rotate(' + f(-roll) + ' ' + f(cx) + ' ' + f(cy) + ')">' + s.ticks + '</g>' : s.ticks)
    + s.index
    + flag
    + '</svg>';
}
